 day=["Prototype interactions in code to test ideas fast", "Build and document design-system components", "Translate Figma designs into pixel-perfect, accessible UI", "Add motion and micro-interactions", "Audit accessibility and consistency"],
 tools=["Figma", "HTML", "CSS", "TypeScript", "React", "Framer Motion", "Storybook", "SVG", "Canvas/WebGL"],
 roles=["Design Engineer", "UX Engineer", "UI Engineer", "Design Systems Engineer"],
