 phases=[
  PH("Design fundamentals", "Weeks 1–6", "See like a designer: layout, type, colour and hierarchy.", [
   N("Visual design principles", "Hierarchy, alignment, contrast, repetition and white space: why some screens feel calm and others chaotic.", ["hierarchy", "grids", "spacing scales", "alignment"], ["rm-ux"]),
   N("Typography", "Choosing, pairing and setting type so it's readable and expressive.", ["type scales", "line length & height", "font pairing", "variable fonts"], ["mdn-css"]),
   N("Colour", "Palettes, contrast and colour in dark mode.", ["colour spaces (OKLCH)", "contrast ratios", "semantic colour tokens"], ["wcag"]),
   N("Figma", "The industry's design tool: frames, auto layout, components and variables.", ["auto layout", "components & variants", "variables", "dev mode"], [("Figma: Help Center", "https://help.figma.com/")]),
   N("UX basics", "User research, flows and usability testing.", ["user flows", "usability tests", "heuristics"], ["rm-ux"]),
  ], ("Redesign a real app screen", "Pick an app you use, redesign one screen in Figma with a clear rationale, then write up before/after.")),
  PH("Front-end craft", "Weeks 7–18", "Build interfaces that match the design exactly and work for everyone.", [
   N("Modern CSS", "Layout, custom properties, container queries, :has() and cascade layers.", ["Grid & Flexbox", "custom properties", "container queries", "cascade layers"], ["mdn-css", "grid"]),
   N("JavaScript & TypeScript", "Enough programming to build real interactive components.", ["DOM & events", "TypeScript", "modules"], ["jsinfo", "ts"]),
   N("React components", "Composable, accessible components with clean APIs.", ["props API design", "composition", "controlled vs uncontrolled"], ["react"], core="s4m2"),
   N("Accessibility in depth", "Keyboard patterns, screen readers and ARIA authoring practices.", ["focus management", "ARIA patterns", "screen reader testing", "reduced motion"], ["mdn-a11y", ("WAI-ARIA Authoring Practices", "https://www.w3.org/WAI/ARIA/apg/")]),
   N("SVG & icons", "Crisp vector graphics you can style and animate.", ["viewBox", "paths", "sprite systems", "animating SVG"], [("MDN: SVG", "https://developer.mozilla.org/en-US/docs/Web/SVG")]),
  ]),
  PH("Motion & interaction", "Weeks 19–28", "Make interfaces feel alive without making them slow or dizzying.", [
   N("Animation principles", "Easing, timing and choreography: motion that explains rather than decorates.", ["easing curves", "durations", "stagger", "spatial continuity"], [("MDN: CSS animations", "https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_animations")]),
   N("CSS & JS animation", "Transitions, keyframes, the Web Animations API and spring physics.", ["transitions", "keyframes", "WAAPI", "springs"], [("MDN: Web Animations API", "https://developer.mozilla.org/en-US/docs/Web/API/Web_Animations_API")]),
   N("View transitions", "Native animated transitions between states and pages.", ["startViewTransition", "shared elements"], [("MDN: View Transition API", "https://developer.mozilla.org/en-US/docs/Web/API/View_Transition_API")]),
   N("Canvas & WebGL", "Generative visuals and 3D on the web.", ["Canvas 2D", "three.js", "shaders"], ["threejs", "mdn-webgl"], opt=True),
   N("Performance of motion", "60fps animations: animate transform and opacity, avoid layout thrash.", ["compositing", "will-change", "measuring jank"], ["webdev"]),
  ], ("Interaction showcase", "A gallery of five polished micro-interactions (toggle, drag-to-reorder, toast stack, command palette, shared-element transition), each accessible and respecting reduced motion.")),
  PH("Design systems", "Months 7–12", "Scale design across teams and products.", [
   N("Design tokens", "Colours, spacing, type and radii as data, synced between Figma and code.", ["token tiers", "theming", "Style Dictionary"], [("Design Tokens Community Group", "https://www.designtokens.org/")]),
   N("Component libraries", "Build, document and version a component library.", ["Storybook", "headless components", "semantic versioning"], [("Storybook docs", "https://storybook.js.org/docs")]),
   N("Visual regression testing", "Catch unintended visual changes automatically.", ["screenshot diffs", "Playwright"], ["playwright"]),
   N("Working with designers", "Shared language, handoff, critique and prototyping to settle debates.", ["design critique", "prototypes", "documentation"], ["rm-ux"]),
  ], ("Mini design system", "Tokens, ten documented components in Storybook, light/dark themes, accessibility tests and a demo app built only from them.")),
 ],
